import itertools

S = [3, 34, 7, 12, 5, 26, 11, 8, 15, 2, 19, 21]
T = 40

def find_subsets(nums, target):
    results = []
    n = len(nums)
    # explore all subset masks
    for r in range(1, n + 1):
        for combo in itertools.combinations(nums, r):
            if sum(combo) == target:
                results.append(list(combo))
    return results

solutions = find_subsets(S, T)
